COMUNS = ['geral_ia_disse']
MENSAGEM_INATIVO = 'Este app responde a dúvidas de estudantes, professores, gestores escolares e pais ou responsáveis. Escolha o seu perfil e o assunto na lista ou reescreva a pergunta.'

def aplicar(sits):
    """Acrescenta os dois perfis novos às fichas comuns e junta as fichas próprias de gestor escolar e de responsável."""
    por_id = {s['id']: s for s in sits}
    for id_ in COMUNS:
        por_id[id_]['perfis'] = por_id[id_]['perfis'] + list(sit_ge.GE) + list(FA)
    return sits + sit_ge.SITUACOES + SITUACOES


# v5.18: perguntas típicas da família que não achavam ficha (teste da v5.17, T3 e T6).
_IA = r'(chat ?gpt|chat\w*|gpt|gemini|copilot|ia|inteligencia artificial|robo)'
CONCEITOS['fa_usa_dever'] = (r'(?<!do meu )(?<!da minha )(?<!dos meus )(?<!das minhas )\b(filh[oa]s?|net[oa]s?|entead[oa]s?|sobrinh[oa]s?|menin[oa]|el[ea]) (so |sempre |ja |agora |tambem )?((usa|usam|usou|ta usando|esta usando|anda usando) .{0,30}\b' + _IA + r'\b.{0,35}\b(dever\w*|licao|licoes|tarefas?|trabalhos?|estud\w+|redac\w+|pesquis\w+|provas?|em casa|materias?)\b|(faz|fez|fazem|estuda|estudam|pesquisa|pesquisam|tira duvidas?) .{0,30}\b' + _IA + r'\b)'
                             r'|\b(filh[oa]s?|net[oa]s?|entead[oa]s?) usar (a |o )?' + _IA + r' (n[oa]s?|para|pra|em) .{0,12}\b(tarefas?|dever\w*|licao|licoes|trabalhos?|estud\w+|redac\w+)\b')
CONCEITOS['fa_acompanhar'] = (r'\b(ver|ler|olhar|acessar|monitor\w+|acompanh\w+|fiscaliz\w+|vigi\w+|control\w+|supervision\w+|conferir|checar) .{0,25}\b(conversas?|historico|mensagens|o que (el[ea]|meu filho|minha filha|meus filhos) (faz|pergunta|escreve|digita|conversa|pesquisa)\w*)\b'
                              r'|\b(monitor\w+|acompanh\w+|supervision\w+|control\w+) (o que )?(meu filho|minha filha|meus filhos|o uso (del[ea]|d[oa] (meu|minha)))\b')
CONCEITOS['fa_qual_ia'] = (r'\b(qual|quais|que) (e |sao |seria )?(a |o |as |os )?(melhor(es)? )?(ia|ias|chat\w*|aplicativos?|apps?|ferramentas?|robos?)\b.{0,40}\b(segur\w+|indicad\w+|recomend\w+|adequad\w+|apropriad\w+|melhor(es)?|bo[am]s?|confiave(l|is)|permitid\w+)\b.{0,30}\b(criancas?|filh[oa]s?|net[oa]s?|menin[oa]s?|adolescentes?|\d{1,2} anos|idade)\b')
_por_id = {s['id']: s for s in SITUACOES}
_por_id['fa_casa']['exige'] += '|fa_usa_dever|fa_acompanhar'
_por_id['fa_casa']['exclui'] = (_por_id['fa_casa']['exclui'] + ' declarar').strip()
_por_id['fa_conta']['exige'] += '|fa_qual_ia'
_por_id['fa_app_escola']['exclui'] = (_por_id['fa_app_escola']['exclui'] + ' fa_qual_ia').strip()


